const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + itemBasePremium(item),
    0,
  );
  const afterPolicyModifiers =
    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE);

  return roundUp(afterPolicyModifiers + PROCESSING_FEE);
};
